  ('demo-entroterra-enna', 1, 1, 'demo-piazza-armerina-borgo', 'afternoon', null),
  ('demo-entroterra-enna', 2, 0, 'demo-morgantina', 'morning', null),
  ('demo-entroterra-enna', 3, 0, 'demo-scala-caltagirone', 'morning', null),
